struct SplitflapRecord {
  char ch;
  SplitflapBitmap full;
  SplitflapBitmap top;
  SplitflapBitmap bottom;
};

static const SplitflapRecord SPLITFLAP_RECORDS[] = {
  {'0', {SPLITFLAP_FULL_DIGIT_0, 48, 72}, {SPLITFLAP_TOP_DIGIT_0, 48, 36}, {SPLITFLAP_BOTTOM_DIGIT_0, 48, 36}},
  {'1', {SPLITFLAP_FULL_DIGIT_1, 48, 72}, {SPLITFLAP_TOP_DIGIT_1, 48, 36}, {SPLITFLAP_BOTTOM_DIGIT_1, 48, 36}},
  {'2', {SPLITFLAP_FULL_DIGIT_2, 48, 72}, {SPLITFLAP_TOP_DIGIT_2, 48, 36}, {SPLITFLAP_BOTTOM_DIGIT_2, 48, 36}},
  {'3', {SPLITFLAP_FULL_DIGIT_3, 48, 72}, {SPLITFLAP_TOP_DIGIT_3, 48, 36}, {SPLITFLAP_BOTTOM_DIGIT_3, 48, 36}},
  {'4', {SPLITFLAP_FULL_DIGIT_4, 48, 72}, {SPLITFLAP_TOP_DIGIT_4, 48, 36}, {SPLITFLAP_BOTTOM_DIGIT_4, 48, 36}},
  {'5', {SPLITFLAP_FULL_DIGIT_5, 48, 72}, {SPLITFLAP_TOP_DIGIT_5, 48, 36}, {SPLITFLAP_BOTTOM_DIGIT_5, 48, 36}},
  {'6', {SPLITFLAP_FULL_DIGIT_6, 48, 72}, {SPLITFLAP_TOP_DIGIT_6, 48, 36}, {SPLITFLAP_BOTTOM_DIGIT_6, 48, 36}},
  {'7', {SPLITFLAP_FULL_DIGIT_7, 48, 72}, {SPLITFLAP_TOP_DIGIT_7, 48, 36}, {SPLITFLAP_BOTTOM_DIGIT_7, 48, 36}},
  {'8', {SPLITFLAP_FULL_DIGIT_8, 48, 72}, {SPLITFLAP_TOP_DIGIT_8, 48, 36}, {SPLITFLAP_BOTTOM_DIGIT_8, 48, 36}},
  {'9', {SPLITFLAP_FULL_DIGIT_9, 48, 72}, {SPLITFLAP_TOP_DIGIT_9, 48, 36}, {SPLITFLAP_BOTTOM_DIGIT_9, 48, 36}},
  {':', {SPLITFLAP_FULL_COLON, 48, 72}, {SPLITFLAP_TOP_COLON, 48, 36}, {SPLITFLAP_BOTTOM_COLON, 48, 36}},
  {' ', {SPLITFLAP_FULL_BLANK, 48, 72}, {SPLITFLAP_TOP_BLANK, 48, 36}, {SPLITFLAP_BOTTOM_BLANK, 48, 36}},
};

static const SplitflapBitmap& blankBitmap(SplitflapPart part) {
  const SplitflapRecord& blank = SPLITFLAP_RECORDS[sizeof(SPLITFLAP_RECORDS) / sizeof(SPLITFLAP_RECORDS[0]) - 1];
  if (part == SplitflapPart::Top) return blank.top;
  if (part == SplitflapPart::Bottom) return blank.bottom;
  return blank.full;
}

const SplitflapBitmap& splitflapBitmap(char ch, SplitflapPart part) {
  if (ch >= 'a' && ch <= 'z') ch = ch - 'a' + 'A';
  for (const SplitflapRecord& record : SPLITFLAP_RECORDS) {
    if (record.ch == ch) {
      if (part == SplitflapPart::Top) return record.top;
      if (part == SplitflapPart::Bottom) return record.bottom;
      return record.full;
    }
  }
  return blankBitmap(part);
}
